import sys, bisect
try:
    import ipaddress
    def parse_addr(s): return int(ipaddress.IPv6Address(s)) >> 64
except Exception:
    raise
MASK64 = (1 << 64) - 1

def read_lines(path):
    data = open(path, 'rb').read().decode('ascii')
    lines = data.split('\n')
    if lines and lines[-1] == '': lines.pop()
    return lines

def parse_fib(path):
    out = []
    for line in read_lines(path):
        if line.strip(' \t\r') == '': continue
        toks = line.strip(' \t\r').split()
        assert len(toks) == 2, toks
        a, l = toks[0].rsplit('/', 1)
        up = parse_addr(a)
        plen = int(l)
        assert 0 <= plen <= 64, plen
        hop = int(toks[1])
        assert 0 <= hop <= MASK64 and hop <= 2**32-1
        key = 0 if plen == 0 else up & (MASK64 ^ ((1 << (64-plen)) - 1))
        out.append((key, plen, hop))
    return out

def fib_build(path, naive=False):
    prefixes = parse_fib(path)
    seen = set()
    for key, plen, hop in prefixes:
        assert (key, plen) not in seen, ("dup", key, plen)
        seen.add((key, plen))
    pts = {0}
    for key, plen, hop in prefixes:
        pts.add(key)
        end = (1 << 64) if plen == 0 else key + (1 << (64-plen))
        if end < (1 << 64): pts.add(end)
    pts = sorted(pts)
    ans = [None] * len(pts)
    if naive:
        for i, k in enumerate(pts):
            best = None
            for key, plen, hop in prefixes:
                end = (1 << 64) if plen == 0 else key + (1 << (64-plen))
                if key <= k < end and (best is None or plen > best[0]):
                    best = (plen, hop)
            ans[i] = (-1, -1) if best is None else (best[1], best[0])
    else:
        nxt = list(range(len(pts) + 1))
        def find(x):
            while nxt[x] != x:
                nxt[x] = nxt[nxt[x]]
                x = nxt[x]
            return x
        bylen = {}
        for key, plen, hop in prefixes:
            bylen.setdefault(plen, []).append((key, hop))
        for plen in sorted(bylen, reverse=True):
            for key, hop in bylen[plen]:
                end = (1 << 64) if plen == 0 else key + (1 << (64-plen))
                i = find(bisect.bisect_left(pts, key))
                j = bisect.bisect_left(pts, end)
                while i < j:
                    ans[i] = (hop, plen)
                    nxt[i] = i + 1
                    i = find(i + 1)
        for i in range(len(pts)):
            if ans[i] is None: ans[i] = (-1, -1)
    rows = []
    prev = None
    for p, a in zip(pts, ans):
        if prev is None or a != prev:
            rows.append((p, a)); prev = a
    out = ['PLANB64 1', str(len(rows))]
    for p, (hop, plen) in rows:
        out.append('%016x %d %d' % (p, hop, plen))
    return '\n'.join(out) + '\n'

def load_image(path):
    lines = read_lines(path)
    assert lines[0] == 'PLANB64 1'
    cnt = int(lines[1])
    assert cnt == len(lines) - 2
    keys, vals = [], []
    for l in lines[2:]:
        f = l.split(' ')
        keys.append(int(f[0], 16)); vals.append((int(f[1]), int(f[2])))
    return keys, vals

def lookup(imgpath, tracepath):
    keys, vals = load_image(imgpath)
    res = []
    for line in read_lines(tracepath):
        s = line.strip(' \t\r')
        if s == '': continue
        up = parse_addr(s)
        i = bisect.bisect_right(keys, up) - 1
        assert i >= 0
        res.append('%d %d' % vals[i])
    return ('\n'.join(res) + '\n') if res else ''

if __name__ == '__main__':
    if sys.argv[1] == 'build':
        naive = len(sys.argv) > 3 and sys.argv[3] == 'naive'
        sys.stdout.write(fib_build(sys.argv[2], naive))
    else:
        sys.stdout.write(lookup(sys.argv[2], sys.argv[3]))
